css:
@page {
  size: A4;
  margin: 0;
}

.print-format {
  padding: 0 !important;
  margin: 0 !important;
  margin-top: 0mm !important;
  margin-bottom: 0mm !important;
  margin-left: 0mm !important;
  margin-right: 0mm !important;
  min-height: 0 !important;
  max-width: none !important;
}

.action-banner {
  display: none !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  overflow: hidden !important;
}

.print-format-gutter {
  margin: 0 !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

.print-format-preview {
  padding: 0 !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  margin: 0;
  padding: 0;
}

.print-page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;

  background-image: var(--page-bg);
  background-repeat: no-repeat;
  background-position: center center;
  background-size: 210mm 297mm;

  page-break-after: always;
}

.print-page:last-child {
  page-break-after: auto;
}

.field {
  position: absolute;
  font-size: 10px;
  line-height: 1.25;
  color: #000;
  white-space: normal;
}

.field-supplier {
  top: 57mm;
  left: 35mm;
  width: 60mm;
}

.field-supplier-name {
  top: 62mm;
  left: 18mm;
  width: 100mm;
}

.field-supplier-address {
  top: 67mm;
  left: 18mm;
  width: 105mm;
  min-height: 16mm;
}

.field-ref {
  top: 86.5mm;
  left: 30mm;
  width: 82mm;
}

.field-po-no {
  top: 57mm;
  left: 146mm;
  width: 55mm;
}

.field-date {
  top: 63mm;
  left: 146mm;
  width: 55mm;
}

.field-required-date {
  top: 75mm;
  left: 146mm;
  width: 55mm;
}

.field-credit {
  top: 83.5mm;
  left: 146mm;
  width: 50mm;
}

.item-table-wrapper {
  position: absolute;
  top: 105mm;
  left: 10mm;
  width: 191.6mm;
}

.item-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  font-size: 9px;
  color: #000;
}

.item-table th,
.item-table td {
  border: none;
  padding: 1.5mm;
  vertical-align: top;
  line-height: 1.25;
}

.col-no {
  width: 16mm;
  text-align: center;
}

.col-item {
  width: 73mm;
  text-align: left;
}

.col-loc {
  width: 10.5mm;
  text-align: center;
}

.col-qty {
  width: 27mm;
  text-align: center;
}

.col-rate {
  width: 22mm;
  text-align: right;
}

.col-discount {
  width: 17mm;
  text-align: right;
}

.col-amount {
  width: 27mm;
  text-align: right;
}

.field-gross {
  top: 229mm;
  left: 173mm;
  width: 30mm;
  text-align: right;
}

.field-less-discount {
  top: 235.5mm;
  left: 173mm;
  width: 30mm;
  text-align: right;
}

.field-after-discount {
  top: 242mm;
  left: 173mm;
  width: 30mm;
  text-align: right;
}

.field-vat {
  top: 248mm;
  left: 173mm;
  width: 30mm;
  text-align: right;
}

.field-net {
  top: 256mm;
  left: 173mm;
  width: 30mm;
  text-align: right;
  font-weight: bold;
}

.field-amount-text {
  top: 256mm;
  left: 16mm;
  width: 105mm;
}

html:
{%- macro page(bg) -%}
{% set supplier_quotations = [] %}
{% for row in doc.items %}
  {% if row.supplier_quotation and row.supplier_quotation not in supplier_quotations %}
    {% set _ = supplier_quotations.append(row.supplier_quotation) %}
  {% endif %}
{% endfor %}
  <div
    class="print-page"
    style="--page-bg: url('{{ bg }}');"
  >

    <!-- Supplier -->
    <div class="field field-supplier">
      {{ doc.supplier or "" }}
    </div>

    <div class="field field-supplier-name">
      {{ doc.supplier_name or "" }}
    </div>

    <div class="field field-supplier-address">
      {{ (doc.address_display or "") | safe }}
    </div>

    <!-- Reference -->
    <div class="field field-ref">
      {{ supplier_quotations | join(", ") }}
    </div>

    <!-- Document info -->
    <div class="field field-po-no">
      {{ doc.name }}
    </div>

    <div class="field field-date">
      {{ format_date(doc.transaction_date) }}
    </div>

    <div class="field field-required-date">
      {{ format_date(doc.schedule_date) }}
    </div>

    <div class="field field-credit">
      {{ doc.payment_terms_template or "" }}
    </div>

    <!-- Item table -->
    <div class="item-table-wrapper">
      <table class="item-table">
        <tbody>
          {% for row in doc.items %}
            <tr>
              <td class="col-no">
                {{ loop.index }}
              </td>

              <td class="col-item">
                {{ row.item_code }} : {{ row.item_name }}
              </td>

              <td class="col-loc">
                {{ row.warehouse or "" }}
              </td>

              <td class="col-qty">
                {{ frappe.format(row.qty, {"fieldtype": "Float"}) }} {{ row.uom or "" }}
              </td>

              <td class="col-rate">
                {{ print_currency(row.price_list_rate or row.rate, doc.currency) }}
              </td>

              <td class="col-discount">
                {% if row.discount_amount and row.discount_amount > 0 %}{{ print_currency(row.discount_amount, doc.currency) }}{% endif %}
              </td>

              <td class="col-amount">
                {{ print_currency(row.amount, doc.currency) }}
              </td>
            </tr>
          {% endfor %}
        </tbody>
      </table>
    </div>

    <!-- Totals -->
    <div class="field field-gross">
      {{ print_currency(doc.total or 0, doc.currency) }}
    </div>

    <div class="field field-less-discount">
      {{ print_currency(doc.discount_amount or 0, doc.currency) }}
    </div>

    <div class="field field-after-discount">
      {{ print_currency(doc.net_total or 0, doc.currency) }}
    </div>

    <div class="field field-vat">
      {{ print_currency(doc.total_taxes_and_charges or 0, doc.currency) }}
    </div>

    <div class="field field-net">
      {{ print_currency(doc.grand_total or 0, doc.currency) }}
    </div>

    <!-- Amount in Thai words -->
    <div class="field field-amount-text">
      ({{ number_to_thai_currency(doc.grand_total or 0, doc.currency) }}).
    </div>

  </div>
{%- endmacro -%}

{%- set bg1 = "/assets/connect_diagnostics_core/images/print_formats/purchase-order-1.png" -%}
{%- set bg2 = "/assets/connect_diagnostics_core/images/print_formats/purchase-order-2.png" -%}

{{ page(bg1) }}
{{ page(bg2) }}
